public readonly record struct UIRect(float X, float Y, float Width, float Height);

public sealed class UILayout
{
    private UILayout(UiLayoutState state) => State = state;

    internal UiLayoutState State { get; }

    public static UILayout Fill() => Anchored(
        new Vector2(0.0f, 0.0f),
        new Vector2(1.0f, 1.0f),
        new Vector2(0.0f, 0.0f),
        new Vector2(0.0f, 0.0f));

    public static UILayout Absolute(float x, float y, float width, float height) =>
        Absolute(new UIRect(x, y, width, height));

    public static UILayout Absolute(UIRect rect)
    {
        UIValidation.Finite(rect.X, nameof(rect.X));
        UIValidation.Finite(rect.Y, nameof(rect.Y));
        UIValidation.NonNegative(rect.Width, nameof(rect.Width));
        UIValidation.NonNegative(rect.Height, nameof(rect.Height));
        return Anchored(
            new Vector2(0.0f, 0.0f),
            new Vector2(0.0f, 0.0f),
            new Vector2(rect.X, rect.Y),
            new Vector2(rect.X + rect.Width, rect.Y + rect.Height));
    }

    public static UILayout Anchored(
        Vector2 anchorMin,
        Vector2 anchorMax,
        Vector2 offsetMin,
        Vector2 offsetMax)
    {
        UIValidation.Anchor(anchorMin, nameof(anchorMin));
        UIValidation.Anchor(anchorMax, nameof(anchorMax));
        UIValidation.Finite(offsetMin.X, nameof(offsetMin));
        UIValidation.Finite(offsetMin.Y, nameof(offsetMin));
        UIValidation.Finite(offsetMax.X, nameof(offsetMax));
        UIValidation.Finite(offsetMax.Y, nameof(offsetMax));
        return new UILayout(new UiLayoutState
        {
            AnchorMin = new[] { anchorMin.X, anchorMin.Y },
            AnchorMax = new[] { anchorMax.X, anchorMax.Y },
            OffsetMin = new[] { offsetMin.X, offsetMin.Y },
            OffsetMax = new[] { offsetMax.X, offsetMax.Y }
        });
    }
}

public class UIElement
