                    nameof(value), $"Slider value must be between {Min} and {Max}");
            _value = value;
            Canvas.Queue(UiCommandState.SetSliderValue(Canvas.Id, Id, value));
        }
    }

    internal override void ApplyEvent(GameplayUiEvent uiEvent)
    {
        if (uiEvent.FloatValue is float value)
            _value = value;
