public sealed class UICanvas
{
    private readonly ScriptUI _ui;
    private readonly Dictionary<uint, UIElement> _elements = new();
    private uint _nextElementId = 1;

    internal UICanvas(ScriptUI ui, string id)
    {
        _ui = ui;
        Id = id;
    }

    public string Id { get; }

    private UIScaleMode _scaleMode = UIScaleMode.Fixed;
    public UIScaleMode ScaleMode
    {
        get => _scaleMode;
        set
        {
            _scaleMode = value;
            Queue(UiCommandState.SetCanvasScaleMode(Id, value));
        }
