    public UIPanel AddPanel(UILayout layout, UIColor color, int zOrder = 0)
    {
        var id = AllocateElementId();
        Queue(UiCommandState.AddElement(Id, id, UiElementState.Panel(layout, color, zOrder)));
        return Register(new UIPanel(this, id));
    }

    public UIImage AddImage(
        UILayout layout,
        string textureId,
        UIColor? color = null,
        int zOrder = 0)
    {
        UIValidation.Identifier(textureId, nameof(textureId), 256);
        var id = AllocateElementId();
        Queue(UiCommandState.AddElement(
            Id,
            id,
            UiElementState.Image(layout, textureId, color ?? UIColor.White, zOrder)));
        return Register(new UIImage(this, id));
    }

    public UIText AddText(
        UILayout layout,
        string text,
        float fontSize,
        UIColor color,
        int zOrder = 0)
    {
        UIValidation.Text(text, nameof(text));
        UIValidation.Positive(fontSize, nameof(fontSize));
        var id = AllocateElementId();
        Queue(UiCommandState.AddElement(
            Id,
            id,
            UiElementState.Text(layout, text, fontSize, color, zOrder)));
        return Register(new UIText(this, id, text));
    }

    public UIButton AddButton(
        UILayout layout,
        string label,
        string? callbackId,
        UIColor normalColor,
        UIColor hoverColor,
        UIColor pressedColor,
        int zOrder = 0)
    {
        UIValidation.Text(label, nameof(label));
        UIValidation.OptionalIdentifier(callbackId, nameof(callbackId), 128);
        var id = AllocateElementId();
        Queue(UiCommandState.AddElement(
            Id,
            id,
            UiElementState.Button(
                layout,
                label,
                callbackId,
                normalColor,
                hoverColor,
                pressedColor,
                zOrder)));
        return Register(new UIButton(this, id));
    }

    public UIToggle AddToggle(
        UILayout layout,
        string label,
        bool isOn,
        UIColor colorOn,
        UIColor colorOff,
        string? callbackId = null,
        int zOrder = 0)
    {
        UIValidation.Text(label, nameof(label));
        UIValidation.OptionalIdentifier(callbackId, nameof(callbackId), 128);
        var id = AllocateElementId();
        Queue(UiCommandState.AddElement(
            Id,
            id,
            UiElementState.Toggle(
                layout, label, isOn, colorOn, colorOff, callbackId, zOrder)));
        return Register(new UIToggle(this, id, isOn));
    }

    public UICheckbox AddCheckbox(
        UILayout layout,
        string label,
        bool isChecked,
        UIColor color,
        string? callbackId = null,
        int zOrder = 0)
    {
        UIValidation.Text(label, nameof(label));
        UIValidation.OptionalIdentifier(callbackId, nameof(callbackId), 128);
        var id = AllocateElementId();
        Queue(UiCommandState.AddElement(
            Id,
            id,
            UiElementState.Checkbox(
                layout, label, isChecked, color, callbackId, zOrder)));
        return Register(new UICheckbox(this, id, isChecked));
    }

    public UISlider AddSlider(
        UILayout layout,
        string label,
        float value,
        float min,
        float max,
        string? callbackId = null,
        int zOrder = 0)
    {
        UIValidation.Text(label, nameof(label));
        UIValidation.Finite(value, nameof(value));
        UIValidation.Finite(min, nameof(min));
        UIValidation.Finite(max, nameof(max));
        if (min > max || value < min || value > max)
            throw new ArgumentOutOfRangeException(
                nameof(value), "Slider requires min <= value <= max");
        UIValidation.OptionalIdentifier(callbackId, nameof(callbackId), 128);
        var id = AllocateElementId();
        Queue(UiCommandState.AddElement(
            Id,
            id,
            UiElementState.Slider(
                layout, label, value, min, max, callbackId, zOrder)));
        return Register(new UISlider(this, id, value, min, max));
    }

    public UIScrollView AddScrollView(
        UILayout layout,
        float contentWidth,
        float contentHeight,
        UIColor color,
        int zOrder = 0)
    {
        UIValidation.NonNegative(contentWidth, nameof(contentWidth));
        UIValidation.NonNegative(contentHeight, nameof(contentHeight));
        var id = AllocateElementId();
        Queue(UiCommandState.AddElement(
            Id,
            id,
            UiElementState.ScrollView(
                layout, contentWidth, contentHeight, color, zOrder)));
        return Register(new UIScrollView(this, id));
    }

    public void Resize(float width, float height)
    {
        UIValidation.Positive(width, nameof(width));
        UIValidation.Positive(height, nameof(height));
        Queue(UiCommandState.ResizeCanvas(Id, width, height));
    }

    public void Clear()
    {
        Queue(UiCommandState.ClearCanvas(Id));
        _elements.Clear();
        _nextElementId = 1;
    }

    public void Remove() => _ui.RemoveCanvas(this);

    internal void Queue(UiCommandState command) => _ui.Queue(command);

    internal void RemoveElement(uint elementId)
    {
        _elements.Remove(elementId);
        Queue(UiCommandState.RemoveElement(Id, elementId));
    }

    internal void ApplyEvent(GameplayUiEvent uiEvent)
    {
        if (_elements.TryGetValue(uiEvent.ElementId, out var element))
            element.ApplyEvent(uiEvent);
    }

    private T Register<T>(T element) where T : UIElement
    {
        _elements.Add(element.Id, element);
        return element;
    }

    private uint AllocateElementId()
    {
        if (_nextElementId == uint.MaxValue)
            throw new InvalidOperationException($"Canvas '{Id}' exhausted its UI element ids");
        return _nextElementId++;
    }
}

public sealed class ScriptUI
{
    private IReadOnlyList<GameplayUiEvent> _events = Array.Empty<GameplayUiEvent>();
    private readonly Dictionary<string, UICanvas> _canvases = new(StringComparer.Ordinal);
    private readonly List<UiCommandState> _pendingCommands = new();

    // Stateful controls update their C# properties before OnUpdate observes
    // this frame-local interaction snapshot.
    public IReadOnlyList<GameplayUiEvent> Events => _events;

    public UICanvas CreateCanvas(
        string canvasId,
        float width,
        float height,
        UIScaleMode scaleMode = UIScaleMode.Fixed)
    {
        UIValidation.EntityId(canvasId, nameof(canvasId));
        UIValidation.Positive(width, nameof(width));
        UIValidation.Positive(height, nameof(height));
        if (_canvases.ContainsKey(canvasId))
            throw new InvalidOperationException(
                $"Canvas '{canvasId}' is already owned by this script instance");
        var canvas = new UICanvas(this, canvasId);
        _canvases.Add(canvasId, canvas);
        Queue(UiCommandState.CreateCanvas(canvasId, width, height));
        if (scaleMode != UIScaleMode.Fixed)
            canvas.ScaleMode = scaleMode;
        return canvas;
    }

    // Returns true when at least one click in this update has the exact,
    // case-sensitive callback id. Events without a callback remain in Events.
    public bool WasClicked(string callbackId)
    {
        ArgumentNullException.ThrowIfNull(callbackId);
        return _events.Any(uiEvent => string.Equals(
            uiEvent.CallbackId,
            callbackId,
            StringComparison.Ordinal));
    }

    internal void Replace(IReadOnlyList<GameplayUiEventState> events)
    {
        var snapshot = events.Select(uiEvent => new GameplayUiEvent(uiEvent)).ToArray();
        foreach (var uiEvent in snapshot)
        {
            if (_canvases.TryGetValue(uiEvent.CanvasId, out var canvas))
                canvas.ApplyEvent(uiEvent);
        }
        _events = snapshot;
    }

    internal void Queue(UiCommandState command) => _pendingCommands.Add(command);

    internal void RemoveCanvas(UICanvas canvas)
    {
        Queue(UiCommandState.RemoveCanvas(canvas.Id));
        _canvases.Remove(canvas.Id);
    }

    internal void DrainTo(List<GameplayCommandState> commands)
    {
        commands.AddRange(_pendingCommands.Select(GameplayCommandState.UI));
        _pendingCommands.Clear();
    }
}

internal static class UIValidation
{
    public static void Finite(float value, string parameterName)
    {
        if (!float.IsFinite(value))
            throw new ArgumentOutOfRangeException(parameterName, "Value must be finite");
    }

    public static void Positive(float value, string parameterName)
    {
        Finite(value, parameterName);
        if (value <= 0.0f)
            throw new ArgumentOutOfRangeException(parameterName, "Value must be greater than zero");
    }

    public static void NonNegative(float value, string parameterName)
    {
        Finite(value, parameterName);
        if (value < 0.0f)
            throw new ArgumentOutOfRangeException(parameterName, "Value must be non-negative");
    }

    public static void Anchor(Vector2 value, string parameterName)
    {
        Finite(value.X, parameterName);
        Finite(value.Y, parameterName);
        if (value.X < 0.0f || value.X > 1.0f || value.Y < 0.0f || value.Y > 1.0f)
            throw new ArgumentOutOfRangeException(parameterName, "Anchors must be in [0, 1]");
    }

    public static void Text(string value, string parameterName)
    {
        ArgumentNullException.ThrowIfNull(value, parameterName);
        if (System.Text.Encoding.UTF8.GetByteCount(value) > 16384 ||
            value.Any(character => char.IsControl(character) && character != '\n' && character != '\t'))
            throw new ArgumentException(
                "UI text must contain at most 16384 UTF-8 bytes and no unsupported control characters",
                parameterName);
    }

    public static void Identifier(string value, string parameterName, int maxBytes)
    {
        if (string.IsNullOrEmpty(value) ||
            System.Text.Encoding.UTF8.GetByteCount(value) > maxBytes ||
            value.Any(char.IsControl))
            throw new ArgumentException(
                $"Value must contain 1 to {maxBytes} UTF-8 bytes and no control characters",
                parameterName);
    }

    public static void OptionalIdentifier(string? value, string parameterName, int maxBytes)
    {
        if (value != null)
            Identifier(value, parameterName, maxBytes);
    }

    public static void EntityId(string value, string parameterName)
    {
        var valid = !string.IsNullOrEmpty(value) && value.Length <= 128 &&
            value != "." && value != "..";
        if (valid)
        {
            foreach (var character in value)
            {
                if (!char.IsAsciiLetterOrDigit(character) &&
                    character != '_' && character != '-' && character != '.')
                {
                    valid = false;
                    break;
                }
            }
        }
        if (!valid)
            throw new ArgumentException(
                "Canvas ids must contain 1 to 128 ASCII letters, digits, hyphens, " +
                "underscores, or dots (but not '.' or '..').",
                parameterName);
    }
}

// High-level movement intent for scene-authored CharacterController
// components. Commands are deferred and consumed by the controller on its
// next simulation update; scripts never teleport the character.
public sealed class ScriptCharacter
{
    public const float MaxSpeed = 100.0f;
    private readonly Func<string> _ownerId;
    private readonly List<GameplayCommandState> _pending = new();

    internal ScriptCharacter(Func<string> ownerId) => _ownerId = ownerId;

    public void Move(Vector3 direction, float? speed = null) =>
        Control(_ownerId(), direction, jump: false, speed: speed);

    public void Move(Entity entity, Vector3 direction, float? speed = null) =>
        Move(entity?.Id ?? throw new ArgumentNullException(nameof(entity)), direction, speed);

    public void Move(string entityId, Vector3 direction, float? speed = null) =>
        Control(entityId, direction, jump: false, speed: speed);

    public void Jump() => Control(_ownerId(), default, jump: true);

    public void Jump(Entity entity) =>
        Jump(entity?.Id ?? throw new ArgumentNullException(nameof(entity)));

    public void Jump(string entityId) => Control(entityId, default, jump: true);

    public void Control(
        Entity entity,
        Vector3 direction,
        bool jump = false,
        float? speed = null) =>
        Control(
            entity?.Id ?? throw new ArgumentNullException(nameof(entity)),
            direction,
            jump,
            speed);

    public void Control(
        string entityId,
        Vector3 direction,
        bool jump = false,
        float? speed = null)
    {
        UIValidation.EntityId(entityId, nameof(entityId));
        UIValidation.Finite(direction.X, nameof(direction));
        UIValidation.Finite(direction.Y, nameof(direction));
        UIValidation.Finite(direction.Z, nameof(direction));
        if (MathF.Abs(direction.Y) > float.Epsilon)
            throw new ArgumentException("Character direction must be horizontal (Y must be zero)", nameof(direction));
        var horizontalLengthSquared =
            direction.X * direction.X + direction.Z * direction.Z;
        if (horizontalLengthSquared > 1.0002f)
            throw new ArgumentOutOfRangeException(
                nameof(direction),
                "Character direction must have horizontal length no greater than one");
        if (speed is { } requestedSpeed)
        {
            UIValidation.Positive(requestedSpeed, nameof(speed));
            if (requestedSpeed > MaxSpeed)
                throw new ArgumentOutOfRangeException(
                    nameof(speed),
                    $"Character speed must not exceed {MaxSpeed}");
        }
        _pending.Add(GameplayCommandState.CharacterControl(
            entityId,
            direction,
            jump,
            speed));
    }

    internal void DrainTo(List<GameplayCommandState> commands)
    {
        commands.AddRange(_pending);
        _pending.Clear();
    }
}

