}

public sealed class RaycastHit
{
    private readonly ScriptScene _scene;

    internal RaycastHit(PhysicsQueryResultState state, ScriptScene scene)
    {
        EntityId = state.EntityId
            ?? throw new InvalidOperationException("raycast hit arrived without an entity id");
        var point = state.Point
            ?? throw new InvalidOperationException("raycast hit arrived without a point");
        var normal = state.Normal
            ?? throw new InvalidOperationException("raycast hit arrived without a normal");
        Point = new Vector3(point[0], point[1], point[2]);
        Normal = new Vector3(normal[0], normal[1], normal[2]);
        Distance = state.Distance
            ?? throw new InvalidOperationException("raycast hit arrived without a distance");
        Interaction = state.Interaction is null
            ? null
            : new InteractionInfo(state.Interaction);
        _scene = scene;
    }

    public string EntityId { get; }
    public Vector3 Point { get; }
    public Vector3 Normal { get; }
    public float Distance { get; }
    public InteractionInfo? Interaction { get; }
    public Entity? Entity => _scene.FindEntity(EntityId);
}

// The outcome of one physics query, as returned by ScriptPhysics.DrainAll.
// Hit carries the contact payload for hit kinds; EntityIds carries the
// overlap payload for the overlap kind.
public enum PhysicsQueryResultKind
{
    RaycastHit,
    RaycastMiss,
    SphereCastHit,
    SphereCastMiss,
    OverlapSphere,
}

public sealed class PhysicsQueryResult
{
    internal PhysicsQueryResult(PhysicsQuery query, PhysicsQueryResultState state, ScriptScene scene)
    {
        Query = query;
        Kind = state.Kind switch
        {
            "raycast_hit" => PhysicsQueryResultKind.RaycastHit,
            "raycast_miss" => PhysicsQueryResultKind.RaycastMiss,
            "sphere_cast_hit" => PhysicsQueryResultKind.SphereCastHit,
            "sphere_cast_miss" => PhysicsQueryResultKind.SphereCastMiss,
            _ => PhysicsQueryResultKind.OverlapSphere,
        };
        Hit = state.Kind is "raycast_hit" or "sphere_cast_hit"
            ? new RaycastHit(state, scene)
            : null;
        EntityIds = state.Kind == "overlap_sphere"
            ? state.EntityIds ?? (IReadOnlyList<string>)Array.Empty<string>()
            : null;
    }

    public PhysicsQuery Query { get; }
    public PhysicsQueryResultKind Kind { get; }
    public RaycastHit? Hit { get; }
    public IReadOnlyList<string>? EntityIds { get; }
}

public sealed class InteractionTarget
{
    internal InteractionTarget(RaycastHit hit)
    {
        Hit = hit;
        var interaction = hit.Interaction
            ?? throw new InvalidOperationException("interaction target requires interaction metadata");
        Prompt = interaction.Prompt;
        Action = interaction.Action;
        MaxDistance = interaction.MaxDistance;
        Grabbable = interaction.Grabbable;
    }

    public RaycastHit Hit { get; }
    public string EntityId => Hit.EntityId;
    public Entity? Entity => Hit.Entity;
    public Vector3 Point => Hit.Point;
    public Vector3 Normal => Hit.Normal;
    public float Distance => Hit.Distance;
    public string Prompt { get; }
    public string Action { get; }
    public float MaxDistance { get; }
    public bool Grabbable { get; }
}

// Project-facing use/grab convention. Probe excludes the owning entity by
// default and returns a deferred physics query. On the next frame,
// TryGetTarget accepts only enabled engine.interactable hits within their
// authored max_distance. The project decides what each action key does.
public sealed class ScriptInteraction
{
    private readonly ScriptPhysics _physics;
    private readonly Func<string> _ownerId;

    internal ScriptInteraction(ScriptPhysics physics, Func<string> ownerId)
    {
        _physics = physics;
        _ownerId = ownerId;
    }

    public PhysicsQuery Probe(
        Vector3 origin,
        Vector3 direction,
        float maxDistance = 3.0f,
        PhysicsQueryFilter? filter = null)
    {
        var resolvedFilter = new PhysicsQueryFilter
        {
            LayerMask = filter?.LayerMask,
            IncludeSensors = filter?.IncludeSensors ?? false,
            ExcludeEntityId = filter?.ExcludeEntityId ?? _ownerId()
        };
        return _physics.Raycast(origin, direction, maxDistance, resolvedFilter);
    }

    public bool TryGetTarget(PhysicsQuery query, out InteractionTarget target)
    {
        if (_physics.TryGetRaycastHit(query, out var hit) && hit.Interaction is not null)
        {
            target = new InteractionTarget(hit);
            return true;
        }
        target = null!;
        return false;
    }

    public void Grab(
        string jointId,
        Entity grabAnchor,
        InteractionTarget target,
        float breakForce = 0.0f,
        float breakTorque = 0.0f)
    {
        ArgumentNullException.ThrowIfNull(target);
        if (!target.Grabbable)
            throw new InvalidOperationException(
                $"Interaction target '{target.EntityId}' is not marked grabbable");
        var entity = target.Entity
            ?? throw new InvalidOperationException(
                $"Interaction target '{target.EntityId}' no longer exists");
        _physics.Grab(jointId, grabAnchor, entity, breakForce, breakTorque);
    }

    public void ReleaseGrab(string jointId) => _physics.ReleaseGrab(jointId);
}

public sealed class ScriptPhysics
{
    // Mirrors the native query bounds: ray distance and sphere radius are
    // clamped to MaxQueryDistance and overlap results are bounded to
    // MaxOverlapResults sorted entity ids.
    public const float MaxQueryDistance = 10000.0f;
    public const int MaxOverlapResults = 64;
    public const float MaxMutationComponent = 1000000.0f;

    private const float MinDirectionLengthSquared = 1e-12f;

    private readonly ScriptScene _scene;
    private IReadOnlyList<PhysicsEventState> _events = Array.Empty<PhysicsEventState>();
    private readonly Dictionary<uint, PhysicsQueryResultState> _queryResults = new();
    private readonly List<PhysicsQueryState> _pendingQueries = new();
    private readonly List<PhysicsMutationState> _pendingMutations = new();
    private uint _nextQueryId = 1;

    internal ScriptPhysics(ScriptScene scene) => _scene = scene;

    public IReadOnlyList<PhysicsEvent> Events =>
        _events.Select(state => new PhysicsEvent(state, _scene)).ToArray();

    // Queries are deferred: the engine validates and executes them against
    // the physics world at the frame boundary and delivers results with the
    // next frame's context. Invalid arguments throw before anything is
    // queued, surfacing as a script error for this frame.
    public PhysicsQuery Raycast(
        Vector3 origin,
        Vector3 direction,
        float maxDistance,
        PhysicsQueryFilter? filter = null)
    {
        Finite(origin, nameof(origin));
        ValidateDirection(direction, "Raycast");
        UIValidation.Positive(maxDistance, nameof(maxDistance));
        filter?.Validate(nameof(filter));
        var query = AllocateQuery();
        _pendingQueries.Add(PhysicsQueryState.Raycast(
            query.Id,
            origin,
            direction,
            Math.Min(maxDistance, MaxQueryDistance),
            PhysicsQueryFilterState.From(filter)));
        return query;
    }

    // Sweeps a sphere along a direction and reports the closest hit. The hit
    // payload mirrors a raycast: contact point and outward normal on the hit
    // collider plus the sweep travel distance.
    public PhysicsQuery SphereCast(
        Vector3 origin,
        float radius,
        Vector3 direction,
        float maxDistance,
        PhysicsQueryFilter? filter = null)
    {
        Finite(origin, nameof(origin));
        UIValidation.Positive(radius, nameof(radius));
        ValidateDirection(direction, "SphereCast");
        UIValidation.Positive(maxDistance, nameof(maxDistance));
        filter?.Validate(nameof(filter));
        var query = AllocateQuery();
        _pendingQueries.Add(PhysicsQueryState.SphereCast(
            query.Id,
            origin,
            Math.Min(radius, MaxQueryDistance),
            direction,
            Math.Min(maxDistance, MaxQueryDistance),
            PhysicsQueryFilterState.From(filter)));
        return query;
    }

    public PhysicsQuery OverlapSphere(
        Vector3 center,
        float radius,
        PhysicsQueryFilter? filter = null)
    {
        Finite(center, nameof(center));
        UIValidation.Positive(radius, nameof(radius));
        filter?.Validate(nameof(filter));
        var query = AllocateQuery();
        _pendingQueries.Add(PhysicsQueryState.OverlapSphere(
            query.Id,
            center,
            Math.Min(radius, MaxQueryDistance),
            PhysicsQueryFilterState.From(filter)));
        return query;
    }

    // Forces and impulses are deferred and resolved by persistent entity id.
    // They execute at the start of the next safe physics step.
    public void ApplyForce(Entity entity, Vector3 force) =>
        ApplyForce(entity?.Id ?? throw new ArgumentNullException(nameof(entity)), force);

    public void ApplyForce(string entityId, Vector3 force)
    {
        ValidateMutation(entityId, force, nameof(force));
        _pendingMutations.Add(PhysicsMutationState.ApplyForce(entityId, force));
    }

    public void ApplyImpulse(Entity entity, Vector3 impulse) =>
        ApplyImpulse(entity?.Id ?? throw new ArgumentNullException(nameof(entity)), impulse);

    public void ApplyImpulse(string entityId, Vector3 impulse)
    {
        ValidateMutation(entityId, impulse, nameof(impulse));
        _pendingMutations.Add(PhysicsMutationState.ApplyImpulse(entityId, impulse));
    }

    public void ApplyTorque(Entity entity, Vector3 torque) =>
        ApplyTorque(entity?.Id ?? throw new ArgumentNullException(nameof(entity)), torque);

    public void ApplyTorque(string entityId, Vector3 torque)
    {
        ValidateMutation(entityId, torque, nameof(torque));
        _pendingMutations.Add(PhysicsMutationState.ApplyTorque(entityId, torque));
    }

    public void ApplyTorqueImpulse(Entity entity, Vector3 torqueImpulse) =>
        ApplyTorqueImpulse(
            entity?.Id ?? throw new ArgumentNullException(nameof(entity)),
            torqueImpulse);

    public void ApplyTorqueImpulse(string entityId, Vector3 torqueImpulse)
    {
        ValidateMutation(entityId, torqueImpulse, nameof(torqueImpulse));
        _pendingMutations.Add(
            PhysicsMutationState.ApplyTorqueImpulse(entityId, torqueImpulse));
    }

    // Creates or replaces a persistent joint at the next frame boundary.
    // Updating is intentionally the same operation: submit the same joint id
    // with new settings and the native backend replaces it incrementally.
    public void CreateJoint(
        string jointId,
        Entity bodyA,
        Entity bodyB,
        PhysicsJointSettings? settings = null) =>
        CreateJoint(
            jointId,
            bodyA?.Id ?? throw new ArgumentNullException(nameof(bodyA)),
            bodyB?.Id ?? throw new ArgumentNullException(nameof(bodyB)),
            settings);

    public void CreateJoint(
        string jointId,
        string bodyAId,
        string bodyBId,
        PhysicsJointSettings? settings = null)
    {
        UIValidation.EntityId(jointId, nameof(jointId));
        UIValidation.EntityId(bodyAId, nameof(bodyAId));
        UIValidation.EntityId(bodyBId, nameof(bodyBId));
        if (StringComparer.Ordinal.Equals(bodyAId, bodyBId))
            throw new ArgumentException("Joint bodies must be different entities", nameof(bodyBId));
        settings ??= new PhysicsJointSettings();
        ValidateJointSettings(settings);
        _pendingMutations.Add(
            PhysicsMutationState.CreateJoint(jointId, bodyAId, bodyBId, settings));
    }

    public void UpdateJoint(
        string jointId,
        Entity bodyA,
        Entity bodyB,
        PhysicsJointSettings settings) =>
        CreateJoint(jointId, bodyA, bodyB, settings);

    public void RemoveJoint(string jointId)
    {
        UIValidation.EntityId(jointId, nameof(jointId));
        _pendingMutations.Add(PhysicsMutationState.RemoveJoint(jointId));
    }

    // Convenience operation for a gravity-gun/hand grab. `grabAnchor` is
    // normally a kinematic rigid body driven by the player or camera.
    public void Grab(
        string jointId,
        Entity grabAnchor,
        Entity body,
        float breakForce = 0.0f,
        float breakTorque = 0.0f)
    {
        CreateJoint(
            jointId,
            grabAnchor,
            body,
            new PhysicsJointSettings
            {
                Type = PhysicsJointType.Fixed,
                BreakForce = breakForce,
                BreakTorque = breakTorque
            });
    }

    public void ReleaseGrab(string jointId) => RemoveJoint(jointId);

    public bool TryGetRaycastHit(PhysicsQuery query, out RaycastHit hit)
    {
        if (_queryResults.TryGetValue(query.Id, out var state) && state.Kind == "raycast_hit")
        {
            hit = new RaycastHit(state, _scene);
            return true;
        }
        hit = null!;
        return false;
    }

    public bool TryGetSphereCastHit(PhysicsQuery query, out RaycastHit hit)
    {
        if (_queryResults.TryGetValue(query.Id, out var state) && state.Kind == "sphere_cast_hit")
        {
            hit = new RaycastHit(state, _scene);
            return true;
        }
        hit = null!;
        return false;
    }

    public bool TryGetOverlapResult(PhysicsQuery query, out IReadOnlyList<string> entityIds)
    {
        if (_queryResults.TryGetValue(query.Id, out var state) && state.Kind == "overlap_sphere")
        {
            entityIds = state.EntityIds ?? (IReadOnlyList<string>)Array.Empty<string>();
            return true;
        }
        entityIds = null!;
        return false;
    }

    // Drains every result for this frame in one call, ordered by query id —
    // the batch counterpart to the per-handle TryGet methods. Drained
    // results are consumed: TryGetRaycastHit/TryGetSphereCastHit/
    // TryGetOverlapResult no longer resolve them afterwards.
    public List<PhysicsQueryResult> DrainAll()
    {
        var drained = _queryResults
            .OrderBy(pair => pair.Key)
            .Select(pair => new PhysicsQueryResult(new PhysicsQuery(pair.Key), pair.Value, _scene))
            .ToList();
        _queryResults.Clear();
        return drained;
    }

    internal void Replace(
        IReadOnlyList<PhysicsEventState> events,
        IReadOnlyList<PhysicsQueryResultState> queryResults)
    {
        _events = events;
        _queryResults.Clear();
        foreach (var result in queryResults)
            _queryResults[result.QueryId] = result;
    }

    internal void DrainTo(List<GameplayCommandState> commands)
    {
        commands.AddRange(_pendingQueries.Select(GameplayCommandState.PhysicsQuery));
        commands.AddRange(_pendingMutations.Select(GameplayCommandState.PhysicsMutation));
        _pendingQueries.Clear();
        _pendingMutations.Clear();
    }

    private static void Finite(Vector3 value, string parameterName)
    {
        UIValidation.Finite(value.X, parameterName);
        UIValidation.Finite(value.Y, parameterName);
        UIValidation.Finite(value.Z, parameterName);
    }

    private static void ValidateDirection(Vector3 direction, string queryKind)
    {
        Finite(direction, nameof(direction));
        if (direction.X * direction.X + direction.Y * direction.Y + direction.Z * direction.Z
            <= MinDirectionLengthSquared)
            throw new ArgumentException($"{queryKind} direction must be non-zero", nameof(direction));
    }

    private static void ValidateMutation(string entityId, Vector3 value, string parameterName)
    {
        UIValidation.EntityId(entityId, nameof(entityId));
        Finite(value, parameterName);
        if (MathF.Abs(value.X) > MaxMutationComponent ||
            MathF.Abs(value.Y) > MaxMutationComponent ||
            MathF.Abs(value.Z) > MaxMutationComponent)
            throw new ArgumentOutOfRangeException(
                parameterName,
                $"Physics mutation components must not exceed {MaxMutationComponent}");
    }

    private static void ValidateJointSettings(PhysicsJointSettings settings)
    {
        Finite(settings.AnchorA, nameof(settings.AnchorA));
        Finite(settings.AnchorB, nameof(settings.AnchorB));
        Finite(settings.Axis, nameof(settings.Axis));
        if (settings.Type is PhysicsJointType.Revolute or PhysicsJointType.Prismatic &&
            settings.Axis.X * settings.Axis.X +
                settings.Axis.Y * settings.Axis.Y +
                settings.Axis.Z * settings.Axis.Z <= MinDirectionLengthSquared)
            throw new ArgumentException(
                "Revolute and prismatic joint axes must be non-zero",
                nameof(settings.Axis));
        ValidateNonNegativeBounded(settings.BreakForce, nameof(settings.BreakForce));
        ValidateNonNegativeBounded(settings.BreakTorque, nameof(settings.BreakTorque));
        if (settings.Limits is { } limits)
        {
            ValidateBounded(limits.Min, nameof(limits.Min));
            ValidateBounded(limits.Max, nameof(limits.Max));
            if (limits.Min > limits.Max)
                throw new ArgumentException("Joint limit Min must not exceed Max", nameof(settings.Limits));
            ValidateNonNegativeBounded(limits.Stiffness, nameof(limits.Stiffness));
            ValidateNonNegativeBounded(limits.Damping, nameof(limits.Damping));
        }
        if (settings.Motor is { } motor)
        {
            ValidateBounded(motor.TargetVelocity, nameof(motor.TargetVelocity));
            ValidateBounded(motor.TargetPosition, nameof(motor.TargetPosition));
            ValidateNonNegativeBounded(motor.Stiffness, nameof(motor.Stiffness));
            ValidateNonNegativeBounded(motor.Damping, nameof(motor.Damping));
        }
    }

    private static void ValidateBounded(float value, string parameterName)
    {
        UIValidation.Finite(value, parameterName);
        if (MathF.Abs(value) > MaxMutationComponent)
            throw new ArgumentOutOfRangeException(
                parameterName,
                $"Physics mutation values must not exceed {MaxMutationComponent}");
    }

    private static void ValidateNonNegativeBounded(float value, string parameterName)
    {
        ValidateBounded(value, parameterName);
        if (value < 0.0f)
            throw new ArgumentOutOfRangeException(parameterName, "Value must be non-negative");
    }

    private PhysicsQuery AllocateQuery()
    {
        if (_nextQueryId == uint.MaxValue)
            throw new InvalidOperationException("Script exhausted its physics query ids");
        return new PhysicsQuery(_nextQueryId++);
    }
}

// Correlates a deferred component query with its snapshot. Queries execute
// at the next frame boundary; the handle is frame-local and only meaningful
// to ScriptComponents.TryGet/IsMissing on the frame after it was issued.
public readonly record struct ComponentQuery(uint Id);

// One field value in a component snapshot or a SetComponent payload. Wire
// type names mirror the engine's component value model: bool, int, uint,
// float, str, enum, asset, vec3, quat, color, list, map.
public readonly record struct ComponentValue
{
    internal const int MaxValueDepth = 16;
    internal const int MaxListItems = 256;
    internal const int MaxStringBytes = 4096;

    private readonly string? _type;
    private readonly object? _value;
    private readonly int _depth;

    private ComponentValue(string type, object? value, int depth)
    {
        _type = type;
        _value = value;
        _depth = depth;
    }

    public string Type => _type ?? throw new InvalidOperationException(
        "ComponentValue is default-initialized; use one of the From* factories");

    public static ComponentValue FromBool(bool value) => new("bool", value, 0);

    public static ComponentValue FromInt(long value) => new("int", value, 0);

    public static ComponentValue FromUInt(ulong value) => new("uint", value, 0);

    public static ComponentValue FromFloat(float value)
    {
        UIValidation.Finite(value, nameof(value));
        return new("float", value, 0);
    }

    public static ComponentValue FromString(string value)
    {
        ValidateString(value, nameof(value));
        return new("str", value, 0);
    }

    public static ComponentValue FromEnum(string value)
    {
        ValidateString(value, nameof(value));
        return new("enum", value, 0);
    }

    public static ComponentValue FromAsset(string assetId)
    {
        ValidateString(assetId, nameof(assetId));
        return new("asset", assetId, 0);
    }

    public static ComponentValue FromVector3(Vector3 value)
    {
        UIValidation.Finite(value.X, nameof(value));
        UIValidation.Finite(value.Y, nameof(value));
        UIValidation.Finite(value.Z, nameof(value));
        return new("vec3", new[] { value.X, value.Y, value.Z }, 0);
    }

    public static ComponentValue FromQuaternion(Quaternion value)
    {
        UIValidation.Finite(value.X, nameof(value));
        UIValidation.Finite(value.Y, nameof(value));
        UIValidation.Finite(value.Z, nameof(value));
        UIValidation.Finite(value.W, nameof(value));
        return new("quat", new[] { value.X, value.Y, value.Z, value.W }, 0);
    }

    public static ComponentValue FromColor(float r, float g, float b, float a)
    {
        UIValidation.Finite(r, nameof(r));
        UIValidation.Finite(g, nameof(g));
        UIValidation.Finite(b, nameof(b));
        UIValidation.Finite(a, nameof(a));
        return new("color", new[] { r, g, b, a }, 0);
    }

    public static ComponentValue FromList(IReadOnlyList<ComponentValue> items)
    {
        ArgumentNullException.ThrowIfNull(items);
        if (items.Count > MaxListItems)
            throw new ArgumentException(
                $"Component lists hold at most {MaxListItems} items", nameof(items));
        return new("list", items.ToArray(), ChildDepth(items, nameof(items)));
    }

    public static ComponentValue FromMap(IReadOnlyDictionary<string, ComponentValue> fields)
    {
        ArgumentNullException.ThrowIfNull(fields);
        if (fields.Count > MaxListItems)
            throw new ArgumentException(
                $"Component maps hold at most {MaxListItems} entries", nameof(fields));
        var copy = new Dictionary<string, ComponentValue>(StringComparer.Ordinal);
        foreach (var pair in fields)
        {
            ScriptComponents.ValidateFieldName(pair.Key, nameof(fields));
            copy[pair.Key] = pair.Value;
        }
        return new("map", copy, ChildDepth(copy.Values, nameof(fields)));
    }

    public static implicit operator ComponentValue(bool value) => FromBool(value);
    public static implicit operator ComponentValue(int value) => FromInt(value);
    public static implicit operator ComponentValue(long value) => FromInt(value);
    public static implicit operator ComponentValue(uint value) => FromUInt(value);
    public static implicit operator ComponentValue(ulong value) => FromUInt(value);
    public static implicit operator ComponentValue(float value) => FromFloat(value);
    public static implicit operator ComponentValue(string value) => FromString(value);
    public static implicit operator ComponentValue(Vector3 value) => FromVector3(value);
    public static implicit operator ComponentValue(Quaternion value) => FromQuaternion(value);

    public bool AsBool() => Expect("bool").GetBoolean();

    public long AsInt() => Expect("int").GetInt64();

    public ulong AsUInt() => Expect("uint").GetUInt64();

    public float AsFloat() => Expect("float").GetSingle();

    public string AsString() => Expect("str").GetString() ?? "";

    public string AsEnum() => Expect("enum").GetString() ?? "";

    public string AsAsset() => Expect("asset").GetString() ?? "";

    public Vector3 AsVector3()
    {
        var values = ExpectFloatArray("vec3", 3);
        return new Vector3(values[0], values[1], values[2]);
    }

    public Quaternion AsQuaternion()
    {
        var values = ExpectFloatArray("quat", 4);
        return new Quaternion(values[0], values[1], values[2], values[3]);
    }

    public (float R, float G, float B, float A) AsColor()
    {
        var values = ExpectFloatArray("color", 4);
        return (values[0], values[1], values[2], values[3]);
    }

    public IReadOnlyList<ComponentValue> AsList()
    {
        if (Type != "list")
            throw Mismatch("list");
        if (_value is IReadOnlyList<ComponentValue> items)
            return items;
        var list = new List<ComponentValue>();
        foreach (var item in AsElement().EnumerateArray())
            list.Add(FromElement(item));
        return list;
    }

    public IReadOnlyDictionary<string, ComponentValue> AsMap()
    {
        if (Type != "map")
            throw Mismatch("map");
        if (_value is IReadOnlyDictionary<string, ComponentValue> map)
            return map;
        var fields = new Dictionary<string, ComponentValue>(StringComparer.Ordinal);
        foreach (var property in AsElement().EnumerateObject())
            fields[property.Name] = FromElement(property.Value);
        return fields;
    }

    internal static ComponentValue FromState(ComponentValueState state) =>
        new(state.Type, state.Value, 0);

    internal ComponentValueState ToState()
    {
        object? wire = _value switch
        {
            IReadOnlyList<ComponentValue> items =>
                items.Select(item => item.ToState()).ToArray(),
            IReadOnlyDictionary<string, ComponentValue> fields =>
                fields.ToDictionary(
                    pair => pair.Key,
                    pair => pair.Value.ToState(),
                    StringComparer.Ordinal),
            _ => _value
        };
        return new ComponentValueState
        {
            Type = Type,
            Value = JsonSerializer.SerializeToElement(wire)
        };
    }

    private static ComponentValue FromElement(JsonElement element)
    {
        var type = element.TryGetProperty("type", out var typeElement)
            ? typeElement.GetString() ?? ""
            : "";
        var value = element.TryGetProperty("value", out var valueElement)
            ? valueElement
            : default;
        return new ComponentValue(type, value, 0);
    }

    private JsonElement Expect(string expectedType)
    {
        if (Type != expectedType)
            throw Mismatch(expectedType);
        return AsElement();
    }

    private InvalidOperationException Mismatch(string expectedType) =>
        new($"Component value holds '{Type}', not '{expectedType}'");

    private JsonElement AsElement() =>
        _value is JsonElement element
            ? element
            : JsonSerializer.SerializeToElement(_value);

    private float[] ExpectFloatArray(string expectedType, int count)
    {
        var element = Expect(expectedType);
        if (element.ValueKind != JsonValueKind.Array || element.GetArrayLength() != count)
            throw new InvalidOperationException(
                $"Component value of type '{expectedType}' must hold {count} numbers");
        var values = new float[count];
        var index = 0;
        foreach (var item in element.EnumerateArray())
            values[index++] = item.GetSingle();
        return values;
    }

    private static int ChildDepth(IEnumerable<ComponentValue> children, string parameterName)
    {
        var depth = 1 + children.Aggregate(0, (max, child) => Math.Max(max, child._depth));
        if (depth > MaxValueDepth)
            throw new ArgumentException(
                $"Component values nest at most {MaxValueDepth} levels deep", parameterName);
        return depth;
    }

    private static void ValidateString(string? value, string parameterName)
    {
        ArgumentNullException.ThrowIfNull(value, parameterName);
        if (System.Text.Encoding.UTF8.GetByteCount(value) > MaxStringBytes ||
            value.Any(char.IsControl))
            throw new ArgumentException(
                $"Component strings contain at most {MaxStringBytes} UTF-8 bytes and no control characters",
                parameterName);
    }
}

// A point-in-time snapshot of one component's fields, delivered with a
// frame's gameplay context. Snapshots are frame-local: issue another query
// to observe later writes.
public sealed class ComponentSnapshot
{
    private readonly IReadOnlyDictionary<string, ComponentValueState> _fields;

    internal ComponentSnapshot(
        string entityId,
        string componentType,
        IReadOnlyDictionary<string, ComponentValueState> fields)
    {
        EntityId = entityId;
        ComponentType = componentType;
        _fields = fields;
    }

    public string EntityId { get; }
    public string ComponentType { get; }

    public bool HasField(string field)
    {
        ArgumentNullException.ThrowIfNull(field);
        return _fields.ContainsKey(field);
    }

    public ComponentValue GetField(string field)
    {
        ArgumentNullException.ThrowIfNull(field);
        if (!_fields.TryGetValue(field, out var state))
            throw new KeyNotFoundException(
                $"Component '{ComponentType}' on '{EntityId}' has no field '{field}'");
        return ComponentValue.FromState(state);
    }

    public bool GetBool(string field) => GetField(field).AsBool();
    public long GetInt(string field) => GetField(field).AsInt();
    public ulong GetUInt(string field) => GetField(field).AsUInt();
    public float GetFloat(string field) => GetField(field).AsFloat();
    public string GetString(string field) => GetField(field).AsString();
    public string GetEnum(string field) => GetField(field).AsEnum();
    public string GetAsset(string field) => GetField(field).AsAsset();
    public Vector3 GetVector3(string field) => GetField(field).AsVector3();
    public Quaternion GetQuaternion(string field) => GetField(field).AsQuaternion();
    public (float R, float G, float B, float A) GetColor(string field) => GetField(field).AsColor();
    public IReadOnlyList<ComponentValue> GetList(string field) => GetField(field).AsList();
    public IReadOnlyDictionary<string, ComponentValue> GetMap(string field) => GetField(field).AsMap();
}

// Deferred read/write access to the engine's built-in components beyond
// Transform. Access is registry-driven: a component type is reachable when
// its engine registry entry declares a script access level and carries scene
// serde hooks — there is no client-side allow-list. The queryable set is
// currently engine.camera, engine.light, engine.audio_source,
// engine.audio_listener, engine.physics.rigid_body, engine.physics.collider,
// engine.physics.physics_material, engine.gravity_source, engine.nav_agent,
// and — query-only — engine.character_controller; docs/COMPONENT_SCRIPT_ACCESS.md
// holds the full audited matrix. Writes to query-only components fail with a
// SCRIPT_COMPONENT_READ_ONLY script error, unknown or dedicated-API keys
// (engine.transform, engine.canvas) fail with SCRIPT_COMPONENT_UNKNOWN, and
// malformed fields with SCRIPT_COMPONENT_PAYLOAD_INVALID.
// Reads are deferred queries executed at the frame boundary, mirroring
// ScriptPhysics: Query returns a frame-local handle and TryGet delivers the
// snapshot with the next frame. Writes merge the provided fields into the
// component after this frame's script callbacks complete.
public sealed class ScriptComponents
{
    internal const int MaxPendingQueriesPerFrame = 256;
    internal const int MaxFieldsPerWrite = 64;

    private readonly List<ComponentQueryState> _pendingQueries = new();
    private readonly List<GameplayCommandState> _pendingWrites = new();
    private readonly Dictionary<uint, ComponentQueryResultState> _queryResults = new();
    private uint _nextQueryId = 1;

    public ComponentQuery Query(string entityId, string componentType)
    {
        ValidateEntityId(entityId, nameof(entityId));
        ValidateTypeKey(componentType, nameof(componentType));
        if (_pendingQueries.Count >= MaxPendingQueriesPerFrame)
            throw new InvalidOperationException(
                $"Scripts may queue at most {MaxPendingQueriesPerFrame} component queries per frame");
        var query = AllocateQuery();
        _pendingQueries.Add(new ComponentQueryState
        {
            QueryId = query.Id,
            EntityId = entityId,
            ComponentType = componentType
        });
        return query;
    }

    public void Set(
        string entityId,
        string componentType,
        IReadOnlyDictionary<string, ComponentValue> fields)
    {
        ValidateEntityId(entityId, nameof(entityId));
        ValidateTypeKey(componentType, nameof(componentType));
        ArgumentNullException.ThrowIfNull(fields);
        if (fields.Count == 0)
            throw new ArgumentException("Set requires at least one field", nameof(fields));
        if (fields.Count > MaxFieldsPerWrite)
            throw new ArgumentException(
                $"Set accepts at most {MaxFieldsPerWrite} fields per call", nameof(fields));
        foreach (var field in fields.Keys)
            ValidateFieldName(field, nameof(fields));
        _pendingWrites.Add(GameplayCommandState.SetComponent(entityId, componentType, fields));
    }

    public void SetField(string entityId, string componentType, string field, ComponentValue value) =>
        Set(
            entityId,
            componentType,
            new Dictionary<string, ComponentValue> { [field] = value });

    public bool TryGet(ComponentQuery query, out ComponentSnapshot snapshot)
    {
        if (_queryResults.TryGetValue(query.Id, out var result) &&
            result.Kind == "snapshot" &&
            result.Fields != null)
        {
            snapshot = new ComponentSnapshot(result.EntityId, result.ComponentType, result.Fields);
            return true;
        }
        snapshot = null!;
        return false;
    }

    // True when the queried entity exists but does not have the component.
    public bool IsMissing(ComponentQuery query) =>
        _queryResults.TryGetValue(query.Id, out var result) && result.Kind == "missing";

    internal void Replace(IReadOnlyList<ComponentQueryResultState> results)
    {
        _queryResults.Clear();
        foreach (var result in results)
            _queryResults[result.QueryId] = result;
    }

    internal void DrainTo(List<GameplayCommandState> commands)
    {
        commands.AddRange(_pendingQueries.Select(GameplayCommandState.ComponentQuery));
        _pendingQueries.Clear();
        commands.AddRange(_pendingWrites);
        _pendingWrites.Clear();
    }

    private ComponentQuery AllocateQuery()
    {
        if (_nextQueryId == uint.MaxValue)
            throw new InvalidOperationException("Script exhausted its component query ids");
        return new ComponentQuery(_nextQueryId++);
    }

    internal static void ValidateFieldName(string? field, string parameterName)
    {
        if (!IsValidKey(field))
            throw new ArgumentException(
                "Component field names must contain 1 to 128 ASCII letters, digits, " +
                "hyphens, underscores, or dots.",
                parameterName);
    }

    private static void ValidateTypeKey(string? componentType, string parameterName)
    {
        if (!IsValidKey(componentType))
            throw new ArgumentException(
                "Component type keys must be registered keys such as 'engine.audio_source' " +
                "containing 1 to 128 ASCII letters, digits, hyphens, underscores, or dots.",
                parameterName);
    }

    private static void ValidateEntityId(string? entityId, string parameterName)
    {
        if (!IsValidKey(entityId) || entityId == "." || entityId == "..")
            throw new ArgumentException(
                "Entity ids must contain 1 to 128 ASCII letters, digits, hyphens, " +
                "underscores, or dots (but not '.' or '..'); entity ids are not file paths.",
                parameterName);
    }

    private static bool IsValidKey(string? value)
    {
        if (string.IsNullOrEmpty(value) || value.Length > 128)
            return false;
        foreach (var character in value)
        {
            if (!char.IsAsciiLetterOrDigit(character) &&
                character != '_' && character != '-' && character != '.')
                return false;
        }
        return true;
    }
}

// A frame-local view of one persistent ECS entity. Entity ids are resolved by
// the engine at the command boundary; managed code never receives raw ECS
// handles that can become stale after a scene change.
public sealed class Entity
{
    private readonly ScriptScene _scene;
    private readonly ScriptTransform? _transform;

    internal Entity(string id, EntitySnapshotState snapshot, ScriptScene scene)
    {
        Id = id;
        _scene = scene;
        _transform = snapshot.Transform == null
            ? null
            : new ScriptTransform(
                snapshot.Transform,
                () => scene.QueueTransform(id, snapshot.Transform));
    }

    public string Id { get; }
    public bool HasTransform => _transform != null;
    public ScriptTransform Transform => _transform ?? throw new InvalidOperationException(
        $"Entity '{Id}' has no Transform component");

    // Destruction is deferred until all script callbacks for the frame have
    // completed. OnDestroy runs before the native entity is released.
    public void Destroy() => _scene.Destroy(Id);

    // Component reads are deferred queries executed at the frame boundary,
    // exactly like physics queries: the snapshot becomes available through
    // Scene.Components.TryGet on the next frame. Writes merge the provided
    // fields into the component after this frame's script callbacks complete.
    public ComponentQuery QueryComponent(string componentType) =>
        _scene.Components.Query(Id, componentType);

    public void SetComponent(
        string componentType,
        IReadOnlyDictionary<string, ComponentValue> fields) =>
        _scene.Components.Set(Id, componentType, fields);

    public void SetComponentField(string componentType, string field, ComponentValue value) =>
        _scene.Components.SetField(Id, componentType, field, value);
}

public sealed class ScriptScene
{
    private IReadOnlyDictionary<string, EntitySnapshotState> _entities =
        new Dictionary<string, EntitySnapshotState>();
    private readonly Dictionary<string, TransformState> _pendingTransforms =
        new(StringComparer.Ordinal);
    private readonly List<GameplayCommandState> _pendingCommands = new();

    internal ScriptComponents Components { get; } = new();

    public IEnumerable<Entity> Entities =>
        _entities.Select(pair => new Entity(pair.Key, pair.Value, this));

    public bool Exists(string entityId)
    {
        ValidateEntityId(entityId, nameof(entityId));
        return _entities.ContainsKey(entityId);
    }

    public Entity? FindEntity(string entityId)
    {
        ValidateEntityId(entityId, nameof(entityId));
        return _entities.TryGetValue(entityId, out var snapshot)
            ? new Entity(entityId, snapshot, this)
            : null;
    }

    public Entity GetEntity(string entityId) => FindEntity(entityId)
        ?? throw new KeyNotFoundException($"Entity '{entityId}' does not exist in this frame");

    public void DestroySelf() => _pendingCommands.Add(GameplayCommandState.DestroySelf());

    public void Destroy(string entityId)
    {
        ValidateEntityId(entityId, nameof(entityId));
        _pendingCommands.Add(GameplayCommandState.DestroyEntity(entityId));
    }

    // Creation is deferred until every script callback for this frame has
    // completed. The entity becomes visible through Entities/FindEntity on
    // the next frame; no raw or provisional ECS handle is exposed here.
    public void CreateEntity(string entityId) =>
        CreateEntity(entityId, new Vector3(0.0f, 0.0f, 0.0f));

    public void CreateEntity(string entityId, Vector3 translation)
    {
        ValidateEntityId(entityId, nameof(entityId));
        _pendingCommands.Add(GameplayCommandState.CreateEntity(
            entityId,
            new TransformState
            {
                Translation = new[] { translation.X, translation.Y, translation.Z }
            }));
    }

    // Prefab instantiation is deferred until every script callback for this
    // frame has completed, exactly like CreateEntity. prefabId is the cooked
    // prefab asset id from the project manifest. The spawned root takes the
    // first free persistent id from prefabId, prefabId-2, ...; every other
    // spawned entity takes '<rootId>.<prefab-local id>'. The new hierarchy
    // becomes visible through Entities/FindEntity on the next frame.
    public void Spawn(string prefabId)
    {
        ValidatePrefabId(prefabId, nameof(prefabId));
        _pendingCommands.Add(GameplayCommandState.SpawnPrefab(prefabId, null));
    }

    // The translation override replaces the prefab root's Transform
    // translation; the prefab's own rotation and scale are preserved.
    public void Spawn(string prefabId, Vector3 translation)
    {
        ValidatePrefabId(prefabId, nameof(prefabId));
        _pendingCommands.Add(GameplayCommandState.SpawnPrefab(
            prefabId,
            new[] { translation.X, translation.Y, translation.Z }));
    }

    // Queue a scene change for the engine to perform after the current script
    // update. sceneId is a key from game.project.json's `scenes` object.
    public void Load(string sceneId)
    {
        if (!IsValidSceneId(sceneId))
            throw new ArgumentException(
                "Scene.Load(sceneId) requires a game.project.json `scenes` key containing " +
                "1 to 128 ASCII letters, digits, hyphens, underscores, or dots " +
                "(but not '.' or '..').",
                nameof(sceneId));
        _pendingCommands.Add(GameplayCommandState.LoadScene(sceneId));
    }

    internal void DrainTo(List<GameplayCommandState> commands)
    {
        foreach (var pair in _pendingTransforms)
            commands.Add(GameplayCommandState.SetEntityTransform(pair.Key, pair.Value));
        commands.AddRange(_pendingCommands);
        _pendingTransforms.Clear();
        _pendingCommands.Clear();
    }

    internal void Replace(
        string ownerId,
        TransformState? ownerTransform,
        IReadOnlyDictionary<string, EntitySnapshotState> entities)
    {
        // Compatibility with older runtimes that only sent the owner's
        // top-level Transform and omitted the `entities` map.
        if (!entities.ContainsKey(ownerId))
        {
            var compatible = new Dictionary<string, EntitySnapshotState>(entities);
            compatible[ownerId] = new EntitySnapshotState { Transform = ownerTransform };
            _entities = compatible;
        }
        else
        {
            _entities = entities;
        }
    }

    internal void QueueTransform(string entityId, TransformState transform) =>
        _pendingTransforms[entityId] = transform;

    private static bool IsValidSceneId(string? sceneId)
    {
        if (string.IsNullOrEmpty(sceneId) || sceneId.Length > 128 ||
            sceneId == "." || sceneId == "..")
            return false;
        foreach (var character in sceneId)
        {
            if (!char.IsAsciiLetterOrDigit(character) &&
                character != '_' && character != '-' && character != '.')
                return false;
        }
        return true;
    }

    private static void ValidateEntityId(string? entityId, string parameterName)
    {
        var valid = !string.IsNullOrEmpty(entityId) && entityId.Length <= 128 &&
            entityId != "." && entityId != "..";
        if (valid)
        {
            foreach (var character in entityId!)
            {
                if (!char.IsAsciiLetterOrDigit(character) &&
                    character != '_' && character != '-' && character != '.')
                {
                    valid = false;
                    break;
                }
            }
        }
        if (!valid)
            throw new ArgumentException(
                "Entity ids must contain 1 to 128 ASCII letters, digits, hyphens, " +
                "underscores, or dots (but not '.' or '..'); entity ids are not file paths.",
                parameterName);
    }

    private static void ValidatePrefabId(string? prefabId, string parameterName)
    {
        try
        {
            ValidateEntityId(prefabId, parameterName);
        }
        catch (ArgumentException)
        {
            throw new ArgumentException(
                "Prefab ids must contain 1 to 128 ASCII letters, digits, hyphens, " +
                "underscores, or dots (but not '.' or '..'); prefab ids are not file paths.",
                parameterName);
        }
    }
}

public readonly record struct ScreenRay(Vector3 Origin, Vector3 Direction);

public sealed class ScriptPointer
{
    public Vector2 Position { get; private set; }
    public Vector2 Delta { get; private set; }
    public Vector2 Scroll { get; private set; }
    public Vector2 Viewport { get; private set; }
    public bool PrimaryDown { get; private set; }
    public bool PrimaryPressed { get; private set; }
    public bool PrimaryReleased { get; private set; }
    public bool SecondaryDown { get; private set; }
    public bool MiddleDown { get; private set; }
    public bool Focused { get; private set; }
    public bool InsideViewport { get; private set; }
    public ScreenRay? WorldRay { get; private set; }

    internal void Replace(PointerState state)
    {
        Position = Vector2From(state.Position);
        Delta = Vector2From(state.Delta);
        Scroll = Vector2From(state.Scroll);
        Viewport = Vector2From(state.Viewport);
        PrimaryDown = state.PrimaryDown;
        PrimaryPressed = state.PrimaryPressed;
        PrimaryReleased = state.PrimaryReleased;
        SecondaryDown = state.SecondaryDown;
        MiddleDown = state.MiddleDown;
        Focused = state.Focused;
        InsideViewport = state.InsideViewport;
        WorldRay = state.RayOrigin is { Length: 3 } origin &&
                   state.RayDirection is { Length: 3 } direction
            ? new ScreenRay(Vector3From(origin), Vector3From(direction))
            : null;
    }

    private static Vector2 Vector2From(float[] values) =>
        values is { Length: 2 } ? new Vector2(values[0], values[1]) : default;

    private static Vector3 Vector3From(float[] values) =>
        values is { Length: 3 } ? new Vector3(values[0], values[1], values[2]) : default;
}

public sealed class ScriptCamera
{
    public bool Available { get; private set; }
    public string? EntityId { get; private set; }
    public bool IsPerspective { get; private set; }
    public Vector3 Position { get; private set; }
    public Vector3 Forward { get; private set; }
    public Vector3 Right { get; private set; }
    public Vector3 Up { get; private set; }
    /// Pixel-space [x, y, width, height].
    public IReadOnlyList<float> Viewport { get; private set; } = Array.Empty<float>();
    /// Column-major matrices matching the native renderer.
    public IReadOnlyList<float> ViewProjection { get; private set; } = Array.Empty<float>();
    public IReadOnlyList<float> InverseViewProjection { get; private set; } = Array.Empty<float>();

    internal void Replace(CameraState? state)
    {
        Available = state != null;
        EntityId = state?.EntityId;
        IsPerspective = state?.Perspective ?? false;
        Position = Vector3From(state?.Position);
        Forward = Vector3From(state?.Forward);
        Right = Vector3From(state?.Right);
        Up = Vector3From(state?.Up);
        Viewport = state?.Viewport is { Length: 4 } viewport
            ? Array.AsReadOnly(viewport)
            : Array.Empty<float>();
        ViewProjection = state?.ViewProjection is { Length: 16 } viewProjection
            ? Array.AsReadOnly(viewProjection)
            : Array.Empty<float>();
        InverseViewProjection = state?.InverseViewProjection is { Length: 16 } inverse
            ? Array.AsReadOnly(inverse)
            : Array.Empty<float>();
    }

    private static Vector3 Vector3From(float[]? values) =>
        values is { Length: 3 } ? new Vector3(values[0], values[1], values[2]) : default;
}

public enum SaveEventKind { Saved, Loaded, Failed }

public sealed record SaveEvent(
    string Slot,
    SaveEventKind Kind,
    string? StateJson,
    string? Error);

public sealed class ScriptSave
{
    private readonly List<GameplayCommandState> _pending = new();
    private IReadOnlyList<SaveEvent> _events = Array.Empty<SaveEvent>();

    public IReadOnlyList<SaveEvent> Events => _events;

    public void SaveJson(string slot, string stateJson)
    {
        ValidateSlot(slot);
        if (stateJson is null) throw new ArgumentNullException(nameof(stateJson));
        if (Encoding.UTF8.GetByteCount(stateJson) > 8 * 1024 * 1024)
            throw new ArgumentOutOfRangeException(nameof(stateJson), "Save JSON exceeds 8 MiB.");
        using var _ = JsonDocument.Parse(stateJson);
        _pending.Add(GameplayCommandState.SaveCheckpoint(slot, stateJson));
    }

    public void Save<T>(string slot, T state) =>
        SaveJson(slot, JsonSerializer.Serialize(state));

    public void Load(string slot)
    {
        ValidateSlot(slot);
        _pending.Add(GameplayCommandState.LoadCheckpoint(slot));
    }

    public bool TryGetLoadedJson(string slot, out string stateJson)
    {
        var match = _events.LastOrDefault(item =>
            item.Kind == SaveEventKind.Loaded &&
            string.Equals(item.Slot, slot, StringComparison.Ordinal));
        stateJson = match?.StateJson ?? "";
        return match?.StateJson != null;
    }

    internal void Replace(IEnumerable<SaveEventState> events) =>
        _events = events.Select(item => new SaveEvent(
            item.Slot,
            item.Kind switch
            {
                "saved" => SaveEventKind.Saved,
                "loaded" => SaveEventKind.Loaded,
                _ => SaveEventKind.Failed
            },
            item.StateJson,
            item.Error)).ToArray();

    internal void DrainTo(List<GameplayCommandState> commands)
    {
        commands.AddRange(_pending);
        _pending.Clear();
    }

    private static void ValidateSlot(string? slot)
    {
        var valid = !string.IsNullOrEmpty(slot) && slot.Length <= 64 &&
                    slot != "." && slot != ".." &&
                    slot.All(character => char.IsAsciiLetterOrDigit(character) ||
                                          character is '_' or '-' or '.');
        if (!valid)
            throw new ArgumentException(
                "Save slots must contain 1 to 64 ASCII letters, digits, underscores, hyphens, or dots.",
                nameof(slot));
    }
}

public readonly record struct LogicAssetQuery(uint Id);

public sealed record LogicAssetResult(
    uint QueryId,
    string AssetId,
    string? Json,
    string? Error);

public sealed class ScriptLogicAssets
{
    private readonly List<GameplayCommandState> _pending = new();
    private Dictionary<uint, LogicAssetResult> _results = new();
    private uint _nextQueryId = 1;

    public LogicAssetQuery Query(string assetId)
    {
        ValidateAssetId(assetId);
        var query = new LogicAssetQuery(_nextQueryId++);
        _pending.Add(GameplayCommandState.QueryLogicAsset(query.Id, assetId));
        return query;
    }

    public bool TryGetJson(LogicAssetQuery query, out string json)
    {
        if (_results.TryGetValue(query.Id, out var result) && result.Json != null)
        {
            json = result.Json;
            return true;
        }
        json = "";
        return false;
    }

    public bool TryDeserialize<T>(LogicAssetQuery query, out T? asset)
    {
        if (TryGetJson(query, out var json))
        {
            asset = JsonSerializer.Deserialize<T>(json);
            return asset is not null;
        }
        asset = default;
        return false;
    }

    public LogicAssetResult? Result(LogicAssetQuery query) =>
        _results.TryGetValue(query.Id, out var result) ? result : null;

    internal void Replace(IEnumerable<LogicAssetResultState> results) =>
        _results = results.ToDictionary(
            result => result.QueryId,
            result => new LogicAssetResult(
                result.QueryId, result.AssetId, result.Json, result.Error));

    internal void DrainTo(List<GameplayCommandState> commands)
    {
        commands.AddRange(_pending);
        _pending.Clear();
    }

    private static void ValidateAssetId(string? assetId)
    {
        var valid = !string.IsNullOrEmpty(assetId) && assetId.Length <= 128 &&
                    assetId != "." && assetId != ".." &&
                    assetId.All(character => char.IsAsciiLetterOrDigit(character) ||
                                             character is '_' or '-' or '.');
        if (!valid)
            throw new ArgumentException("Logic asset ID is invalid.", nameof(assetId));
    }
}

// Typed convenience wrapper over the registry-driven audio component. Calls
// remain deferred and are reconciled by the runtime audio system next frame.
public sealed class ScriptAudio
{
    public const string ComponentType = "engine.audio_source";
    private readonly ScriptComponents _components;

    internal ScriptAudio(ScriptComponents components) => _components = components;

    public void Play(
        Entity entity,
        string clipAsset,
        float volume = 1.0f,
        bool looping = false,
        bool spatial = false) =>
        Play(entity.Id, clipAsset, volume, looping, spatial);

    public void Play(
        string entityId,
        string clipAsset,
        float volume = 1.0f,
        bool looping = false,
        bool spatial = false)
    {
        if (!float.IsFinite(volume) || volume < 0.0f || volume > 1.0f)
            throw new ArgumentOutOfRangeException(nameof(volume), "Audio volume must be in [0, 1].");
        _components.Set(entityId, ComponentType, new Dictionary<string, ComponentValue>
        {
            ["clip_asset"] = ComponentValue.FromAsset(clipAsset),
            ["volume"] = volume,
            ["looping"] = looping,
            ["spatial"] = spatial,
            ["playing"] = true
        });
    }

    public void Stop(Entity entity) => Stop(entity.Id);
    public void Stop(string entityId) =>
        _components.SetField(entityId, ComponentType, "playing", false);

    public void SetVolume(Entity entity, float volume) => SetVolume(entity.Id, volume);
    public void SetVolume(string entityId, float volume)
    {
        if (!float.IsFinite(volume) || volume < 0.0f || volume > 1.0f)
            throw new ArgumentOutOfRangeException(nameof(volume), "Audio volume must be in [0, 1].");
        _components.SetField(entityId, ComponentType, "volume", volume);
    }

    public void SetLooping(Entity entity, bool looping) => SetLooping(entity.Id, looping);
    public void SetLooping(string entityId, bool looping) =>
        _components.SetField(entityId, ComponentType, "looping", looping);

    public ComponentQuery Query(Entity entity) => Query(entity.Id);
    public ComponentQuery Query(string entityId) => _components.Query(entityId, ComponentType);
    public bool TryGet(ComponentQuery query, out ComponentSnapshot snapshot) =>
        _components.TryGet(query, out snapshot);
}

// Dedicated animation API. AnimationPlayer is intentionally not writable
// through generic component snapshots because that would overwrite runtime
// state-machine caches and pose ownership.
public sealed class ScriptAnimation
{
    private readonly List<GameplayCommandState> _pending = new();

    public void PlayClip(
        Entity entity,
        string clipAsset,
        bool looping = true,
        float speed = 1.0f,
        bool restart = true) =>
        PlayClip(entity.Id, clipAsset, looping, speed, restart);

    public void PlayClip(
        string entityId,
        string clipAsset,
        bool looping = true,
        float speed = 1.0f,
        bool restart = true)
    {
        ValidateKey(entityId, nameof(entityId));
        ValidateKey(clipAsset, nameof(clipAsset));
        if (!float.IsFinite(speed) || speed <= 0.0f || speed > 16.0f)
            throw new ArgumentOutOfRangeException(nameof(speed), "Animation speed must be in (0, 16].");
        _pending.Add(GameplayCommandState.PlayAnimation(
            entityId, clipAsset, looping, speed, restart));
    }

    public void Pause(Entity entity) => Pause(entity.Id);
    public void Pause(string entityId) => SetPlaying(entityId, false);
    public void Resume(Entity entity) => Resume(entity.Id);
    public void Resume(string entityId) => SetPlaying(entityId, true);

    public void SetFloat(Entity entity, string name, float value) =>
        SetFloat(entity.Id, name, value);
    public void SetFloat(string entityId, string name, float value)
    {
        if (!float.IsFinite(value))
            throw new ArgumentOutOfRangeException(nameof(value), "Animation parameter must be finite.");
        SetParameter(entityId, name, new AnimationParameterState("float", value));
    }

    public void SetInt(Entity entity, string name, int value) => SetInt(entity.Id, name, value);
    public void SetInt(string entityId, string name, int value) =>
        SetParameter(entityId, name, new AnimationParameterState("int", value));

    public void SetBool(Entity entity, string name, bool value) => SetBool(entity.Id, name, value);
    public void SetBool(string entityId, string name, bool value) =>
        SetParameter(entityId, name, new AnimationParameterState("bool", value));

    public void Transition(Entity entity, string state) => Transition(entity.Id, state);
    public void Transition(string entityId, string state)
    {
        ValidateKey(entityId, nameof(entityId));
        ValidateKey(state, nameof(state));
        _pending.Add(GameplayCommandState.TransitionAnimationState(entityId, state));
    }

    public void SetMorphWeights(Entity entity, params float[] weights) =>
        SetMorphWeights(entity.Id, weights);

    public void SetMorphWeights(string entityId, params float[] weights)
    {
        ValidateKey(entityId, nameof(entityId));
        ArgumentNullException.ThrowIfNull(weights);
        if (weights.Length is < 1 or > 8 ||
            weights.Any(weight => !float.IsFinite(weight) || weight < -1.0f || weight > 1.0f))
            throw new ArgumentOutOfRangeException(
                nameof(weights),
                "Morph weights require 1 to 8 finite values in [-1, 1].");
        _pending.Add(GameplayCommandState.SetMorphWeights(entityId, weights));
    }

    internal void DrainTo(List<GameplayCommandState> commands)
    {
        commands.AddRange(_pending);
        _pending.Clear();
    }

    private void SetPlaying(string entityId, bool playing)
    {
        ValidateKey(entityId, nameof(entityId));
        _pending.Add(GameplayCommandState.SetAnimationPlaying(entityId, playing));
    }

    private void SetParameter(string entityId, string name, AnimationParameterState value)
    {
        ValidateKey(entityId, nameof(entityId));
        ValidateKey(name, nameof(name));
        _pending.Add(GameplayCommandState.SetAnimationParameter(entityId, name, value));
    }

    private static void ValidateKey(string? value, string parameterName)
    {
        if (string.IsNullOrEmpty(value) || value.Length > 128 ||
            value == "." || value == ".." ||
            value.Any(character => !char.IsAsciiLetterOrDigit(character) &&
                character is not '_' and not '-' and not '.'))
            throw new ArgumentException(
                "Animation ids and names use 1 to 128 ASCII letters, digits, underscores, hyphens, or dots.",
                parameterName);
    }
}

public abstract partial class EngineBehaviour
{
    private static readonly JsonSerializerOptions JsonOptions = new()
    {
        PropertyNameCaseInsensitive = false
    };

    private ScriptTransform? _transform;
    private bool _transformDirty;

    protected EngineBehaviour()
    {
        Character = new ScriptCharacter(() => EntityId);
        Physics = new ScriptPhysics(Scene);
        Interaction = new ScriptInteraction(Physics, () => EntityId);
        Damage = new ScriptDamage(Scene);
        Ragdoll = new ScriptRagdoll(Scene);
        Pointer = new ScriptPointer();
        Camera = new ScriptCamera();
        Save = new ScriptSave();
        LogicAssets = new ScriptLogicAssets();
        Audio = new ScriptAudio(Scene.Components);
        Animation = new ScriptAnimation();
    }

    public string EntityId { get; private set; } = "";
    public ScriptInput Input { get; } = new();
    public ScriptUI UI { get; } = new();
    public ScriptScene Scene { get; } = new();
    public ScriptCharacter Character { get; }
    public ScriptPhysics Physics { get; }
    public ScriptInteraction Interaction { get; }
    public ScriptDamage Damage { get; }
    public ScriptRagdoll Ragdoll { get; }
    public ScriptPointer Pointer { get; }
    public ScriptCamera Camera { get; }
    public ScriptSave Save { get; }
    public ScriptLogicAssets LogicAssets { get; }
    public ScriptAudio Audio { get; }
    public ScriptAnimation Animation { get; }
    public ScriptComponents Components => Scene.Components;
    public ScriptWorldOrigin WorldOrigin { get; private set; }
    public ScriptTransform Transform => _transform ?? throw new InvalidOperationException(
        $"Script entity '{EntityId}' has no Transform component");

    // Reserved protocol hook. Game code should use EntityId, Input and
    // Transform instead of calling this method directly.
    public void __EngineSetGameplayContext(string contextJson)
    {
        var context = JsonSerializer.Deserialize<GameplayContextState>(contextJson, JsonOptions)
            ?? throw new InvalidOperationException("gameplay context JSON was empty");
        if (!string.Equals(context.ScriptApi, ScriptApiContract.Schema, StringComparison.Ordinal))
            throw new InvalidOperationException(
                $"Gameplay Script API mismatch: engine sent '{context.ScriptApi}', " +
                $"but this game assembly targets '{ScriptApiContract.Schema}'. " +
                "Run `sandbox project sync-script-api <project>` and rebuild scripts.");
        EntityId = context.EntityId;
        Input.Replace(context.InputActions, context.InputTransitions);
        Pointer.Replace(context.Pointer);
        Camera.Replace(context.Camera);
        Save.Replace(context.SaveEvents);
        LogicAssets.Replace(context.LogicAssetResults);
        RuntimeAssets.Replace(context.RuntimeAssetResults);
        Terrain.Replace(context.RuntimeAssetResults);
        UI.Replace(context.UiEvents);
        Physics.Replace(context.PhysicsEvents, context.PhysicsQueryResults);
        Damage.Replace(context.DamageEvents);
        Ragdoll.Replace(context.RagdollEvents);
        Components.Replace(context.ComponentQueryResults);
        Network.Replace(context.Network);
        XR.Replace(context.Xr);
        WorldOrigin = context.WorldOrigin is { Length: 3 } origin
            ? new ScriptWorldOrigin(origin[0], origin[1], origin[2])
            : new ScriptWorldOrigin(0.0, 0.0, 0.0);
        _transform = context.Transform == null
            ? null
            : new ScriptTransform(context.Transform, () => _transformDirty = true);
        Scene.Replace(EntityId, context.Transform, context.Entities);
        _transformDirty = false;
    }

    // Reserved protocol hook. Commands never contain an entity id; the Rust
    // manager binds them to this script instance's owning entity.
    public string __EngineDrainGameplayCommands()
    {
        var commands = new List<GameplayCommandState>();
        if (_transformDirty && _transform != null)
            commands.Add(GameplayCommandState.SetTransform(_transform.State));
        Scene.DrainTo(commands);
        Character.DrainTo(commands);
        UI.DrainTo(commands);
        Physics.DrainTo(commands);
        Damage.DrainTo(commands);
        Ragdoll.DrainTo(commands);
        Components.DrainTo(commands);
        Save.DrainTo(commands);
        LogicAssets.DrainTo(commands);
        Animation.DrainTo(commands);
        RuntimeAssets.DrainTo(commands);
        Terrain.DrainTo(commands);
        Network.DrainTo(commands);
        var json = JsonSerializer.Serialize(commands, JsonOptions);
        _transformDirty = false;
        return json;
    }
}

